  'Angle': { select: { name: 'Funding trigger' } },
  // For the later analytics agent: which model + prompt wrote this, so reply rates can be compared per model/variant
  'Draft model': { rich_text: t($('Config').first().json.draftModel) },
  'Prompt version': { rich_text: t($('Config').first().json.promptVersion) }
};
if (r.channel === 'Email') props['Booking link'] = { url: r.bookingLink };
return { json: { contactPageId: r.contactPageId, name: r.name, company: r.company, channel: r.channel, pass: r.pass,
  passed: r.passedIds, attempts: r.attempt, quality, notionBody: { properties: props } } };

// Summary for the orchestrator / manual run.
const rows = $('Build draft update').all().map(i => i.json);
return [{ json: { drafted: rows.length, passed: rows.filter(r => r.pass).length,
  firstTry: rows.filter(r => r.pass && r.attempts === 1).length, failed: rows.filter(r => !r.pass).length,
  qSum: rows.reduce((a, r) => a + (r.quality || 0), 0), qN: rows.filter(r => r.quality != null).length,
  drafts: rows.map(r => ({ name: r.name, company: r.company, channel: r.channel, passed: r.passed, attempts: r.attempts, quality: r.quality })) } }];

// RUN LOG (upsert): one row per execution in Notion › Runs: runtime, volume, errors, estimated cost.
// This node can run several times per execution (once per branch that reaches it). Counters are summed
// in the execution's custom data, and the same Notion row is updated instead of creating a new one.
const started = $('Config').first().json.startedAt;
const r = $json;
const c = { in: r.drafted, out: r.passed, firstTry: r.firstTry, failed: r.failed, attempts: (r.drafts || []).reduce((a, d) => a + (d.attempts || 1), 0), qSum: r.qSum || 0, qN: r.qN || 0 };
const x = { model: $('Config').first().json.draftModel, prompt: $('Config').first().json.promptVersion };
const view = (c, x) => ({ in: c.in, out: c.out, errors: 0, costEur: Math.round(c.attempts * 0.024 * 1000) / 1000, skip: !c.in,
  quality: c.qN ? Math.round(c.qSum / c.qN * 10) / 10 : null, model: x.model,
  notes: `${c.out}/${c.in} passed (${c.firstTry} on the first try), ${c.failed} to Check manually. ${c.attempts} draft attempts. Model ${x.model}, ${x.prompt}. Avg quality ${c.qN ? (c.qSum / c.qN).toFixed(1) : 'n/a'}/10. Cost estimated (~€0.024 per attempt).` });
const cd = $execution.customData;
let acc = {}; try { acc = JSON.parse(cd.get('runlog') || '{}'); } catch (e) { acc = {}; }
acc.c = acc.c || {};
for (const k of Object.keys(c)) acc.c[k] = (acc.c[k] || 0) + (Number(c[k]) || 0);
const m = view(acc.c, x);
cd.set('runlog', JSON.stringify({ c: acc.c, pageId: acc.pageId || null }));
if (m.skip) return [];
const dur = started ? Math.round((Date.now() - new Date(started).getTime()) / 1000) : null;
const t = v => [{ type: 'text', text: { content: String(v ?? '').slice(0, 1900) } }];
const properties = {
  'Run': { title: t(`Draft ${new Date(started || Date.now()).toISOString().slice(0, 16).replace('T', ' ')}`) },
  'Workflow': { select: { name: 'Draft' } },
  'Status': { select: { name: m.errors ? (m.out > 0 ? 'Partial' : 'Failed') : 'Success' } },
  'Started': { date: { start: started || new Date().toISOString() } },
  'Duration s': { number: dur },
  'Execution ID': { rich_text: t($execution.id) },
  'Items in': { number: m.in ?? null }, 'Items out': { number: m.out ?? null },
  'Errors': { number: m.errors || 0 }, 'Cost EUR': { number: m.costEur ?? null },
  'Notes': { rich_text: t(m.notes) } };
if (m.quality != null) properties['Quality avg'] = { number: m.quality };
if (m.model) properties['Model'] = { rich_text: t(m.model) };
return [{ json: acc.pageId
  ? { method: 'PATCH', url: 'https://api.notion.com/v1/pages/' + acc.pageId, body: { properties } }
  : { method: 'POST', url: 'https://api.notion.com/v1/pages', body: { parent: { database_id: '84a655097a4449588604e918ae009c1b' }, properties } } }];

// Remember the Runs row created in this execution, so a later pass updates it instead of adding a row.
const cd = $execution.customData;
let acc = {}; try { acc = JSON.parse(cd.get('runlog') || '{}'); } catch (e) {}
if (!acc.pageId && $json.id) { acc.pageId = $json.id; cd.set('runlog', JSON.stringify(acc)); }
return [{ json: { runLogPageId: acc.pageId || null } }];
